def f(g):
    h=len(g); w=len(g[0])
    out=[row[:] for row in g]
    nz=lambda v: v not in (0,5)
    def vline(c,r0,r1):
        for dc in (1,-1):
            cc=c+dc
            if not(0<=cc<w) or not any(nz(g[r][cc]) for r in range(h)): continue
            cs=[cc]; d=1 if dc>0 else -1
            while True:
                n=cc+d*len(cs)
                if 0<=n<w and any(nz(g[r][n]) for r in range(h)): cs.append(n)
                else: break
            brows=[r for r in range(r0,r1+1) if any(nz(g[r][x]) for x in cs)]
            if not brows: continue
            b0=brows[0]; bh=brows[-1]-b0+1
            block=[[g[r][x] for x in cs] for r in range(b0,b0+bh)]
            for r in range(r0,r1+1):
                row=block[(r-b0)%bh]
                for i,x in enumerate(cs): out[r][x]=row[i]
    def hline(r,c0,c1):
        for dr in (1,-1):
            rr=r+dr
            if not(0<=rr<h) or not any(nz(g[rr][c]) for c in range(w)): continue
            rs=[rr]; d=1 if dr>0 else -1
            while True:
                n=rr+d*len(rs)
                if 0<=n<h and any(nz(g[n][c]) for c in range(w)): rs.append(n)
                else: break
            bcols=[c for c in range(c0,c1+1) if any(nz(g[x][c]) for x in rs)]
            if not bcols: continue
            bC0=bcols[0]; bw=bcols[-1]-bC0+1
            block=[[g[x][c] for c in range(bC0,bC0+bw)] for x in rs]
            for c in range(c0,c1+1):
                col=[row[(c-bC0)%bw] for row in block]
                for i,x in enumerate(rs): out[x][c]=col[i]
    for c in range(w):
        r=0
        while r<h:
            if g[r][c]==5:
                r0=r
                while r<h and g[r][c]==5: r+=1
                if r-r0>=2: vline(c,r0,r-1)
            else: r+=1
    for r in range(h):
        c=0
        while c<w:
            if g[r][c]==5:
                c0=c
                while c<w and g[r][c]==5: c+=1
                if c-c0>=2: hline(r,c0,c-1)
            else: c+=1
    return out
